const ICONS={spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',card:'M3 5h18v14H3z M3 10h18 M6 15h4',chart:'M4 3v18h17 M8 16v-5 M13 16V7 M18 16V4',route:'M4 5h7v5h9 M17 7l3 3-3 3 M4 19h7v-5h9',bell:'M6 17V9a6 6 0 0112 0v8 M4 17h16 M10 21h4',check:'M5 12l4 4 10-10',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',file:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',settings:'M12 8a4 4 0 100 8 4 4 0 000-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',reset:'M3 9a9 9 0 119 12 M3 3v6h6',clock:'M12 3a9 9 0 100 18 9 9 0 000-18 M12 7v5l4 2',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',search:'M10 3a7 7 0 100 14 7 7 0 000-14 M15 15l6 6',close:'M6 6l12 12 M18 6L6 18',send:'M5 12l7-7 7 7 M12 5v15',money:'M6 4h12 M6 8h12 M8 4c7 0 7 8 0 8l9 8',users:'M9 4a3 3 0 100 6 3 3 0 000-6 M3 20v-3c0-5 12-5 12 0v3 M17 4a3 3 0 010 6 M18 13c3 0 3 4 3 7',play:'M8 4l12 8-12 8z',info:'M12 3a9 9 0 100 18 9 9 0 000-18 M12 11v6 M12 7h.01',edit:'M4 20l4-1L20 7l-4-4L4 15z M13 6l4 4'};
