function interpret(text){
 if(!text.trim()){error('Describe the payments and providers you want to use.');return;}
 state.intentText=text;const bindings={northstar:[],indus:[]};
 const provider='(Northstar(?: Payments)?|Indus(?: PG)?)';
 const patterns=[new RegExp('(\\d+(?:\\.\\d+)?)\\s*%\\s*(?:of\\s+(?:ordinary\\s+)?cards?\\s*)?(?:to|on|with|through|via|for|at)?\\s*'+provider,'ig'),new RegExp(provider+'\\s*(?:(?:gets?|receives?|handles?|at|to|on|is|should get)\\s*)?(?:[:=]\\s*)?(\\d+(?:\\.\\d+)?)\\s*%','ig')];
 for(let j=0;j<patterns.length;j++)for(const m of text.matchAll(patterns[j])){const name=(j===0?m[2]:m[1]).toLowerCase().startsWith('northstar')?'northstar':'indus';bindings[name].push(Number(j===0?m[1]:m[2]));}
 const ns=[...new Set(bindings.northstar)],ip=[...new Set(bindings.indus)],pct=[...text.matchAll(/(\d+(?:\.\d+)?)\s*%/g)];let n=null;
 if(ns.length<=1&&ip.length<=1){if(ns.length&&ip.length&&Math.abs(ns[0]+ip[0]-100)<1e-8)n=ns[0];else if(ns.length&&!ip.length&&pct.length===1)n=ns[0];else if(ip.length&&!ns.length&&pct.length===1)n=100-ip[0];}
 if(n===null&&['percent','customShare'].includes(state.stage)&&/^\s*\d+(?:\.\d+)?\s*%?\s*$/.test(text))n=Number(text.replace('%',''));
 const noBackup=/\bno\s+(?:backup|fallback)|without\s+(?:a\s+)?(?:backup|fallback)/i.test(text);
 if(noBackup){state.ordinaryBackup='no';state.backupFromIntent=true;state.ordinaryBackupConfirmed=false;}
 else if(/backup|fails|failure|fallback/i.test(text)&&/Indus|Cobalt/i.test(text)){state.ordinaryBackup='yes';state.ordinaryBackupProvider=/cobalt/i.test(text)?'cobalt':'indus';state.backupFromIntent=true;state.ordinaryBackupConfirmed=false;}
 if(state.backupFromIntent)decide('ordinaryBackup','Backup interpreted from your message',state.ordinaryBackup==='yes'?backupName()+' permitted':'No backup authorised','Review this explicit choice in the routing draft.','ordinaryBackup');
 invalidate();state.ordinaryOrigin='Read from your message';
 if(n!==null&&n>=0&&n<=100){state.ordinaryB=n;decide('allocation','Interpreted allocation',n+'% Northstar / '+(100-n)+'% Indus PG','Provider names determine the share. Mandatory agreements are checked separately.','percent');advance(state.ordinaryBackup?'draft':'ordinaryBackup',text,'I understood '+n+'% to Northstar and '+(100-n)+'% to Indus PG'+(noBackup?', with no backup.':'.')+' Review this before testing.');}
 else{state.ordinaryB=null;advance('percent',text,pct.length?'I cannot safely assign those percentages. How much should Northstar receive? Indus gets the remainder.':'How much should Northstar receive? “Most” needs an exact percentage.');}
}
function drawerContent(id){const paragraphs=(items)=>items.map(p=>`<p>${p}</p>`).join('');switch(id){case 'savedBrief':return ['Saved partnership brief',table(['Opportunity','Brief'],[['Meridian card share','38% of observed card transactions'],['Historical EMI reach','1,240 matching payments'],['Questions for partner','Eligibility, funding, account activation, dates and alternatives']])+`<p>Saved locally. Nothing was sent or activated.</p>`];case 'guide':return ['How Ray works',paragraphs(['Payment routing decides which payments use each provider and what happens after an eligible failure.','Create starts with your goals and optional agreements. Review starts with saved routing and a specific change or finding.','The agent interprets and explains. Routing checks, calculations and settings revisions are deterministic. You approve the exact change before it is applied.','Decisions records choices and implications. Evidence shows source terms, network context, routing cases and the configuration diff.'])+button('View the workflow','info:workflow',true)];case 'step':return ['About this step',`<p>${esc(prompt())}</p><p>Answer using the decision card. The agent records it, explains the implication and asks the next relevant question.</p>`];case 'prototype':return ['Prototype information',paragraphs(['All companies, offers and figures are fictional sample data. Razorpay is the proposed host platform.','The agent uses scripted conversation and local parsing. This demonstrates the intended AI-native workflow; it is not a connected language model.','Optimizer writes, network data and read-back are simulated. No real merchant settings or payments are changed.','The attachment check validates file metadata. Text terms can be read locally; arbitrary PDFs and images are not automatically extracted or verified with a bank. Attachment contents are not uploaded.','No email, SMS, bank request or teammate message is sent. Their actions prepare local drafts or previews.','Financial estimates retain visible assumptions. Verified means the simulated saved fields match approval, not proven growth, subsidy entitlement or actual volume attainment.'])];case 'workflow':return ['Built on the proposed Razorpay workflow',`<div class="tags">${tag('Proposed architecture','blue')}</div>${[['file','Merchant goals and terms','Input documents, account permissions and commercial data.'],['spark','Interpret and ask','AI structures the intent and resolves unclear requirements.'],['shield','Check and simulate','Deterministic eligibility, rule precedence, economics and version gates.'],['users','Merchant approval','Review the scoped diff and explicitly approve.'],['route','Optimizer execution','A simulated adapter applies only the approved configuration.'],['search','Read-back and monitoring','Compare saved fields and raise contextual review tasks.']].map(([i,t,d])=>`<div class="workflowstep">${icon(i)}<div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}<p>Agentic Studio can orchestrate interpretation and tool calls. Production routing read/write adapters, permissions and network-data access need confirmed Razorpay interfaces; this prototype does not claim an existing public MCP supports those writes.</p>`];case 'accountNorthstar':return ['Northstar merchant account',paragraphs(['NS-VK-2041 is Voltkart’s own merchant account with Northstar Payments. Some bank offers work only through a specific account. The agent checks the account as well as the gateway.'])];case 'accountIndus':return ['Indus PG merchant account',paragraphs(['IP-VK-7713 is Voltkart’s own merchant account with Indus PG. Connection alone does not establish that its EMI methods or offer identifiers are enabled.'])];case 'version':return ['Settings revision',paragraphs(['A revision identifies a saved configuration. Drafting and testing do not change it.','Approval is tied to the revision inspected. If someone changes live settings, the previous approval cannot be reused.'])];case 'offer':return ['Meridian offer terms',`<div class="source">${esc(SAMPLE_OFFER)}</div><p>Suggested relevance does not establish Voltkart’s eligibility or account-specific activation.</p>`];case 'feeTerms':return card('Confirm the negotiated fee',table(['Term','Read from agreement'],[['Indus success fee','₹185, previously ₹200'],['Volume minimum','None'],['Account','Indus PG IP-VK-7713'],['Validity','Until 31 March 2027']])+`<p class="fine">A fee agreement changes the cost comparison. It does not require a particular split.</p><div class="actions">${button('Confirm the fee terms','confirmFee',true)}${button('Save and confirm later','savePending')}</div>`);
case 'infeasible':return card('No feasible routing under these confirmed terms',`<div class="notice red">Exclusive offer scope is ${state.volumeShare}% of qualifying cards. At most ${100-state.volumeShare}% remains for Indus, below its ${state.floor}% overall requirement.</div><p class="fine">I cannot silently relax a mandatory agreement. Confirm an amendment, correct the counting scope or save pending.</p><div class="actions">${button('Review the agreement terms','edit:documents',true)}${button('Save as pending','savePending')}</div>`,'red');
case 'commitment':return ['The commitment’s denominator',paragraphs(['This sample counts qualifying successful card payments over a calendar month. A real agreement might instead count payment value or have a rupee minimum; those are different constraints.','With 4% of total card payments routed exclusively to Northstar, Indus needs at least 15 ÷ 96 = 15.625% of the remaining ordinary payments to reach 15% overall. An ordinary 84/16 candidate projects 15.36% overall.','A split is an allocation plan. Actual successful volume must be reconciled with settled records.','At 1,000 qualifying successful payments per month, 15% on Indus saves ₹15 × 150 = ₹2,250 before other terms. At the combined 15.36% candidate, the corresponding estimate is ₹2,304. These are separate examples from the ₹15.96 contribution comparison.'])];case 'traces':return ['Rule simulation: representative payment cases',table(['Case','Current behaviour','Tested behaviour'],PAYMENTS.map(p=>[esc(p.label),esc(trace(p,false).route),esc(trace(p,true).route)]))+`<p>Issuer, payment method, amount, tenure and validity decide eligibility. An offer exception has precedence within its scope. These checks model routing, not a prediction of completion or reimbursement.</p>`];case 'optimizer':return ['Optimizer: saved routing rules',table(['Priority','Scope','Saved behaviour'],[['1','Meridian eligible EMI',state.live.campaign?account()+' · minimum '+money(state.live.campaign.threshold):'No saved offer exception'],['2','Ordinary cards',state.live.cards.northstar+'% Northstar / '+(100-state.live.cards.northstar)+'% Indus PG'],['3','UPI',state.live.upi.northstar+'% Northstar / '+(100-state.live.upi.northstar)+'% Indus PG']])+`<p>Settings revision ${state.live.version}; last verified revision ${state.live.verified}. This is a read-only view of the simulated saved configuration.</p>`];case 'readiness':return ['Scope-specific readiness',paragraphs(['Ordinary cards need connected accounts and enabled card methods. EMI offers additionally need EMI, the required merchant account, representable routing conditions and confirmed offer activation.','Backup permission and backup capability are checked separately. No required scope is silently removed.'])];case 'enablement':return ['Provider enablement task',paragraphs([`Account: ${state.blockType==='backup'?'Indus PG IP-VK-7713':'Northstar NS-VK-2041'}.`,`Request the required EMI enablement and account-specific offer compatibility through your authorised provider support channel.`,`This prepares a task only. Nothing has been sent and no capability is marked enabled.`])+button('Save routing as pending','savePending',true)];case 'readback':return ['Verified fields',table(['Approved field','Result'],verifiedRows().map(t=>[esc(t),'Matches ✓']))+`<p>Read-back matched the approved fields in the simulated adapter. Actual outcome evidence remains separate.</p>`];case 'mismatch':return ['Saved-result reconciliation',table(['Field','Approved','Returned'],[['Merchant account','NS-VK-2041','IP-VK-7713']])+`<p>The discrepancy stops further writes. A fresh reviewed correction is required; no automatic rollback is assumed.</p>`];case 'teammate':return ['Question for Arjun',paragraphs(['Draft: “You changed UPI from 70/30 to 50/50 on 25 October. Could you confirm the purpose and any commercial constraints before we re-verify it?”','No message has been sent. Use your authorised collaboration channel.'])];case 'notificationLog':return ['Notification activity',state.notificationLog.length?table(['Review','Status','Time'],state.notificationLog.map(n=>[esc(n.title),esc(n.status),esc(n.createdAt)])):'<p>No notification has been created yet.</p>'];case 'nudges':return ['Agent review notifications',[['newcard','New Meridian card offer','Review the match to your payment mix.'],['outage','Northstar disruption','Review a temporary permitted route.'],['saleReview','Post-sale review','Review expired exceptions and saved allocation.'],['campaign','Meridian offer readiness','Confirm two instructions before checking the campaign.'],['performance','Northstar completion update','Compare new evidence within your commercial constraints.'],['amendment','Meridian minimum purchase changed','Open the ₹20,000 to ₹25,000 amendment.'],['drift','Arjun changed UPI routing','Review the current versus verified settings.'],['expiry','Meridian offer ended','Remove only its exception after approval.']].map(([a,t,d])=>`<button class="savedrow" data-action="review:${a}"><span class="nudgeicon">${icon(({newcard:'card',outage:'shield',saleReview:'clock',campaign:'bell',performance:'chart',amendment:'file',drift:'edit',expiry:'clock'})[a])}</span><span><strong>${t}</strong><small>${d}</small></span>${icon('arrow')}</button>`).join('')+`<p>Later-date notifications are independent preview scenarios. They do not imply all events occurred at once.</p>`];case 'payments':case 'reports':return ['Merchant dashboard context',paragraphs(['The native navigation is retained to show where Ray lives. This prototype does not connect to real payment records.'])+button('Open Ray','agentHome',true)];default:return ['More information',paragraphs(['Inspect the confirmed scope, evidence and approval before proceeding.'])];}}
function renderDrawer(){const [title,body]=drawerContent(drawer);$('#overlay').innerHTML=`<div class="modalback"><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${title}</h2><button class="closebtn" data-action="close" aria-label="Close information">${icon('close')}</button></header>${body}</section></div>`;}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){const act=a.dataset.action;if(drawer&&!act.startsWith('info:')&&act!=='close'){drawer='';$('#overlay').innerHTML='';}action(act,a.getAttribute('aria-label')||a.querySelector('strong')?.textContent||a.textContent.trim());return;}if(e.target.classList.contains('modalback')){drawer='';$('#overlay').innerHTML='';}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='theme'){state.theme=t.value;persist();render();return;}if(t.id==='scenario'){setScenario(t.value);return;}if(t.id==='termsFile'){const f=t.files?.[0];if(!f)return;if(!/\.(txt|md)$/i.test(f.name)||f.size>1024*1024){error('Use a text or Markdown file up to 1 MB. For PDFs, paste the relevant clause.');return;}state.terms=await f.text();state.termsOrigin='Uploaded by you: '+f.name;state.documentTab='paste';persist();render();return;}if(t.id==='proofFile'){const f=t.files?.[0];if(!f)return;if(!/\.(pdf|png|jpg|jpeg|txt|md)$/i.test(f.name)||f.size>10*1024*1024){error('Attach a PDF, image or text file up to 10 MB.');return;}state.proof={name:f.name,size:f.size};state.proofReviewed=false;state.partnerConfirmed=false;state.uploadBusy=true;invalidate();render();setTimeout(()=>{state.uploadBusy=false;state.proofReviewed=true;persist();render();},1000);return;}if(t.id==='backupAuthorised'){state.backupAuthorised=t.checked;invalidate();persist();return;}if(t.id==='remindersEnabled'){state.notifications.enabled=t.checked;persist();return;}if(t.id==='partnerConfirmed'){state.partnerConfirmed=t.checked;invalidate();persist();return;}if(t.id==='backupRemovalConfirmed'){state.backupRemovalConfirmed=t.checked;persist();return;}if(t.id==='economicPermission'){state.economics.confirmed=t.checked;invalidate();persist();render();return;}if(t.id==='reminderChannel'){state.notifications.channel=t.value;persist();return;}if(t.id==='reminderLead'){state.notifications.lead=t.value;persist();return;}if(['ordinaryB','threshold','start','end'].includes(t.id)){state[t.id]=t.type==='number'?(t.value===''?null:Number(t.value)):t.value;invalidate();persist();return;}if(Object.hasOwn(state.economics,t.id)){state.economics[t.id]=t.value===''?'':Number(t.value);invalidate();persist();return;}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='chatInput'){state.composerDraft=t.value;return;}if(['terms','intentText','feedbackText','requestedProvider'].includes(t.id)){state[t.id]=t.value;if(t.id==='intentText'){const b=document.querySelector('[data-action="interpret"]');if(b)b.disabled=!t.value.trim();const badge=document.querySelector('label[for="intentText"] .tag');if(badge)badge.textContent=t.value.trim()?'You entered':'Example';}if(t.id==='terms')invalidate();persist();}});
function chatAnswer(text,message){
  state.turns.push({role:'agent',text:prompt()},{role:'user',text},{role:'agent',text:message});
  chatOriginal='';state.chatReply=message;state.ack='';state.error='';persist();render();
}
function submitChat(){
 const text=$('#chatInput').value.trim();if(!text)return;
 state.composerDraft='';state.chatReply='';chatOriginal=text;
 const stage=state.stage, t=text.toLowerCase(), yes=/^(yes|yeah|yep|sure|okay|ok|confirm|confirmed|continue|next|proceed)[.! ]*$/.test(t), no=/^(no|nope|not yet)[.! ]*$/.test(t);
 const go=a=>{action(a);if(chatOriginal){chatOriginal='';state.turns.push({role:'user',text});persist();render();}};
 if(stage==='applying'){chatAnswer(text,'Your approved change is being checked. Please wait for the saved-result status before editing.');return;}
 if(/^(why|explain|how|what does|what is|help|tell me)/i.test(text)){chatAnswer(text,prompt()+' Your Decisions panel shows the choices you have made. Evidence shows the source and payment checks. You can also use the i button for this step.');return;}
 if(/save.*later|save.*draft|do.*later|not ready/i.test(text)){go('savePending');return;}
 if(stage==='home'){if(/create|new|set up/i.test(text)){go('start:create');return;}if(/review|check.*routing/i.test(text)){go('start:review');return;}}
 if(stage==='goal'){
   const goal=/cost|fee|margin|contribution/.test(t)?'cost':/success|completion|going through/.test(t)?'completion':/agreement|deal|offer/.test(t)?'agreements':/split|own|allocation/.test(t)?'split':null;
   if(goal){go('goal:'+goal);return;}
 }
 if(stage==='agreement'){
   if(no||/no.*(agreement|tie.?up|offer)|without.*(agreement|offer)/.test(t)){go('noAgreement');return;}
   if(/suggest|show|explore|available/.test(t)){go('to:growth');return;}
   if(yes||/have|upload|share|paste/.test(t)){go('to:documents');return;}
 }
 if(stage==='documents'){
   if(/sample|example/.test(t)){go('sample:'+(/volume|commitment/.test(t)?'volume':/fee|pricing/.test(t)?'fee':'offer'));return;}
   if(/clause|merchant account|tenure|qualifying|agreement|emi|volume commitment/i.test(text)){state.terms=text;state.termsOrigin='Terms pasted in chat';go('readTerms');return;}
 }
 if(stage==='starter'){
   if(yes||/use.*(starter|suggestion|starting)|suggest.*me/.test(t)){go('useStarter');return;}
   interpret(text);return;
 }
 if(['intent','percent','customShare'].includes(stage)){
   const n=text.match(/^\s*(\d+(?:\.\d+)?)\s*%?\s*$/);
   if(n&&stage!=='intent'){if(+n[1]>100){chatAnswer(text,'The share must be between 0% and 100%. How much should Northstar receive?');return;}go('share:'+n[1]);return;}
   interpret(text);return;
 }
 if(stage==='clarify'){
   if(!/not (mandatory|required)/.test(t)&&/required|mandatory|only northstar|must.*northstar/.test(t)){go('mandatory:required');return;}
   if(/prefer|not mandatory|not required/.test(t)){go('mandatory:preferred');return;}
 }
 if(stage==='learning'){if(/future/.test(t)){go('memory:future');return;}if(/campaign|this offer|only here/.test(t)){go('memory:campaign');return;}}
 if(stage==='activation'){
   if(/pending|still discussing|not active/.test(t)){go('activation:pending');return;}
   if(/active|activated|approved/.test(t)){go('activation:active');return;}
 }
 if(stage==='proof'&&(yes||/confirm.*(proof|approval|evidence)/.test(t))){go('confirmProof');return;}
 if(stage==='backupChoose'&&/cobalt|indus/.test(t)){go('chooseBackup:'+(/cobalt/.test(t)?'cobalt':'indus'));return;}
 if(['backup','ordinaryBackup'].includes(stage)){
   if(/cobalt/.test(t)){state.backupContext=stage==='backup'?'offer':'ordinary';go('chooseBackup:cobalt');return;}
   if(no||/no backup|no fallback|not allowed|no alternative|without.*backup/.test(t)){go(stage==='backup'?'backup:no':'ordinaryBackup:no');return;}
   if(/another|different|other provider/.test(t)){go('pickBackup:'+(stage==='backup'?'offer':'ordinary'));return;}
   if(yes||/indus.*(allow|backup|fail)|backup.*indus|use indus/.test(t)){go(stage==='backup'?'backup:yes':'ordinaryBackup:yes');return;}
 }
 if(stage==='backupRequest'){state.requestedProvider=text;go('saveProviderRequest');return;}
 if(stage==='ordinary'){
   if(/saved|keep|unchanged/.test(t)){go('outside:saved');return;}
   if(/suggest|recommend/.test(t)){go('outside:suggest');return;}
   if(/northstar|indus|split|\d+\s*%/.test(t)){interpret(text);return;}
 }
 if(stage==='draft'){
   if(yes||/confirm.*(draft|routing)|looks good/.test(t)){go('confirmDraft');return;}
   if(/cobalt|indus.*backup|no backup/.test(t)){state.backupContext='ordinary';if(/cobalt/.test(t))go('chooseBackup:cobalt');else go('ordinaryBackup:'+(/no backup/.test(t)?'no':'yes'));return;}
   if(/\d+\s*%|\d+\s*\/\s*\d+/.test(t)){interpret(text);return;}
 }
 if(stage==='readiness'&&(yes||/test|simulate/.test(t))){go('ready');return;}
 if(stage==='simulation'){
   if(/approve|apply/.test(t)){chatAnswer(text,'First check your selected option, then review the exact change. Approval happens on that proposal.');return;}
   if(/current|saved routing/.test(t)){go('option:baseline');return;}
   if(/all agreements|volume floor/.test(t)){go('option:allAgreements');return;}
   if(/northstar only|all.*northstar|100.*northstar/.test(t)){go('option:single');return;}
   if(/recommend|ray.*suggest|protect.*offer/.test(t)){go('recommendOption');return;}
   if(/completion|success rate/.test(t)){go('lens:completion');return;}
   if(/fees|cost/.test(t)){go('lens:cost');return;}
   if(/contribution|margin/.test(t)){go('lens:contribution');return;}
   if(/proposal|review.*change/.test(t)){go('prepare');return;}
   if(yes||/check|test|run|simulate/.test(t)){go('runSimulation');return;}
 }
 if(stage==='proposal'){
   if(/^(i )?approve( and apply)?[.! ]*$/.test(t)){go('apply');return;}
   if(/reject|do not apply/.test(t)){go('reject');return;}
   if(yes){chatAnswer(text,'To apply this exact proposal, type “Approve and apply” or use that button. A general “yes” does not apply routing.');return;}
 }
 if(stage==='verified'&&/home|overview|done|finish/.test(t)){go('routingOverview');return;}
 if(stage==='pending'&&/continue|resume/.test(t)){go('restoreDraft');return;}
 if(stage==='growth'&&/offer|see|show/.test(t)){go('to:offers');return;}
 if(['growth','offers','cardOpportunity'].includes(stage)&&/brief|partnership/.test(t)){go('to:brief');return;}
 if(stage==='brief'&&/save/.test(t)){go('saveBrief');return;}
 if(stage==='brief'&&/continue|without/.test(t)){go('skipGrowth');return;}
 if(stage==='preferences'&&/save|confirm/.test(t)){go('savePreferences');return;}
 // Exact card replies and the unique primary continuation share the card's validation.
 const normal=v=>v.toLowerCase().replace(/<[^>]*>/g,' ').replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w&&!['the','a','an','my','your','please'].includes(w)).join(' ');
 const buttons=[...activeCard().matchAll(/<button\b([^>]*)data-action="([^"]+)"[^>]*>([\s\S]*?)<\/button>/g)].filter(m=>!m[2].startsWith('info:'));
 const direct=buttons.filter(m=>normal(m[3])===normal(text));
 if(direct.length===1&&direct[0][2]!=='apply'){go(direct[0][2]);return;}
 if(yes){const primary=buttons.filter(m=>/class="[^"]*primary/.test(m[1])&&m[2]!=='apply');if(primary.length===1){go(primary[0][2]);return;}}
 const hints={goal:'Tell me your main goal: more completed payments, lower costs, following agreements, or your own split.',agreement:'Do you have terms to share, want to explore offers, or want to continue without an agreement?',ordinaryBackup:'Name Indus PG or Cobalt Pay as backup, say “no backup”, or choose another provider.',draft:'You can confirm the routing draft, change the split, or name a different backup.',simulation:'You can compare current routing, Northstar only, or Ray’s suggestion; then say “check this option”.',proof:'Attach partner approval first, then confirm the evidence. A chat message cannot verify bank activation.'};
 chatAnswer(text,'I’ve received your message, but I need one clarification before changing this draft. '+(hints[stage]||'Please tell me which choice on this card you mean. Your saved routing has not changed.'));
}
document.addEventListener('submit',e=>{if(e.target.id!=='chatForm')return;e.preventDefault();submitChat();});
document.addEventListener('keydown',e=>{if(e.target.id==='chatInput'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();submitChat();return;}if(e.key==='Escape'&&drawer){drawer='';$('#overlay').innerHTML='';}if(e.key==='Tab'&&drawer){const items=[...document.querySelectorAll('#overlay button,#overlay input,#overlay select,#overlay a')];if(items.length&&e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(items.length&&!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
window.PSA={action,start,advance,setScenario,trace,exposure,economics,compliance,selectedShare,signature,canPropose,runChecks,finishApply,getState:()=>clone(state)};
render();
